<?php
require_once dirname(__DIR__).'/app/bootstrap.php';require_login();$uid=current_user_id();$errors=[];$activeNav='messages';$listingId=(int)($_GET['listing']??0);$conversationId=(int)($_GET['conversation']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$body=trim((string)($_POST['body']??''));$conversationId=(int)($_POST['conversation_id']??0);$newListing=(int)($_POST['listing_id']??0);
 if(text_len($body)<2||text_len($body)>2000){flash('error','Messages must be between 2 and 2,000 characters.');redirect(app_path('messages.php'.($conversationId?'?conversation='.$conversationId:($newListing?'?listing='.$newListing:''))));}
 if($newListing){$s=db()->prepare("SELECT id,owner_user_id,slug FROM listings WHERE id=:id AND status='published'");$s->execute([':id'=>$newListing]);$l=$s->fetch();if(!$l||!(int)$l['owner_user_id']||(int)$l['owner_user_id']===$uid){flash('error','This listing does not have an available owner inbox. Use the enquiry form instead.');redirect($l?app_path('index.php?listing='.rawurlencode($l['slug'])):app_path('index.php'));}$owner=(int)$l['owner_user_id'];$i=db()->prepare('INSERT INTO conversations(listing_id,customer_id,owner_id) VALUES(:l,:c,:o) ON CONFLICT(listing_id,customer_id) DO UPDATE SET updated_at=CURRENT_TIMESTAMP');$i->execute([':l'=>$newListing,':c'=>$uid,':o'=>$owner]);$s=db()->prepare('SELECT id FROM conversations WHERE listing_id=:l AND customer_id=:c');$s->execute([':l'=>$newListing,':c'=>$uid]);$conversationId=(int)$s->fetchColumn();}
 $c=db()->prepare('SELECT * FROM conversations WHERE id=:id AND (customer_id=:uc OR owner_id=:uo)');$c->execute([':id'=>$conversationId,':uc'=>$uid,':uo'=>$uid]);$thread=$c->fetch();if(!$thread){flash('error','Conversation not found or access denied.');redirect(app_path('messages.php'));}
 db()->prepare('INSERT INTO messages(conversation_id,sender_id,body) VALUES(:c,:u,:b)')->execute([':c'=>$conversationId,':u'=>$uid,':b'=>text_substr($body,0,2000)]);db()->prepare('UPDATE conversations SET updated_at=CURRENT_TIMESTAMP WHERE id=:id')->execute([':id'=>$conversationId]);$recipient=(int)$thread['customer_id']===$uid?(int)$thread['owner_id']:(int)$thread['customer_id'];notify_user($recipient,'New business message','You received a new message in a LocalGuide conversation.','messages.php?conversation='.$conversationId);flash('success','Message sent.');redirect(app_path('messages.php?conversation='.$conversationId));
}
$threads=db()->prepare('SELECT c.*,l.name listing_name,l.slug listing_slug,cu.name customer_name,ow.name owner_name,(SELECT body FROM messages m WHERE m.conversation_id=c.id ORDER BY m.id DESC LIMIT 1) last_message,(SELECT COUNT(*) FROM messages m WHERE m.conversation_id=c.id AND m.sender_id<>:u AND m.read_at IS NULL) unread FROM conversations c JOIN listings l ON l.id=c.listing_id JOIN users cu ON cu.id=c.customer_id JOIN users ow ON ow.id=c.owner_id WHERE c.customer_id=:uc OR c.owner_id=:uo ORDER BY c.updated_at DESC');$threads->execute([':uc'=>$uid,':uo'=>$uid,':u'=>$uid]);$threads=$threads->fetchAll();
$activeThread=null;$messages=[];if($conversationId){$s=db()->prepare('SELECT c.*,l.name listing_name,l.slug listing_slug,cu.name customer_name,ow.name owner_name FROM conversations c JOIN listings l ON l.id=c.listing_id JOIN users cu ON cu.id=c.customer_id JOIN users ow ON ow.id=c.owner_id WHERE c.id=:id AND (c.customer_id=:uc OR c.owner_id=:uo)');$s->execute([':id'=>$conversationId,':uc'=>$uid,':uo'=>$uid]);$activeThread=$s->fetch();if($activeThread){db()->prepare('UPDATE messages SET read_at=CURRENT_TIMESTAMP WHERE conversation_id=:c AND sender_id<>:u AND read_at IS NULL')->execute([':c'=>$conversationId,':u'=>$uid]);$m=db()->prepare('SELECT m.*,u.name sender_name FROM messages m JOIN users u ON u.id=m.sender_id WHERE m.conversation_id=:c ORDER BY m.id ASC LIMIT 250');$m->execute([':c'=>$conversationId]);$messages=$m->fetchAll();}}
$targetListing=null;if($listingId){$s=db()->prepare("SELECT id,name,slug,owner_user_id FROM listings WHERE id=:id AND status='published'");$s->execute([':id'=>$listingId]);$targetListing=$s->fetch();if($targetListing&&!(int)$targetListing['owner_user_id'])$targetListing=null;}
$pageTitle='Business messages | '.setting('site_name','MetroGuide');$pageDescription='Private messages between customers and local business owners.';include __DIR__.'/includes/header.php';
?>
<main id="main" class="container account-page"><div class="page-intro"><span class="eyebrow">DIRECT BUSINESS MESSAGING</span><h1>Your conversations.</h1><p>Use messages for service questions and follow-ups. Do not send passwords, card details or sensitive personal information.</p></div><?php if($f=get_flash()): ?><div class="alert alert-<?= h($f['type']) ?>"><?= h($f['message']) ?></div><?php endif; ?><div class="lg3-message-layout"><aside class="content-panel"><h2>Inbox</h2><?php if($threads): ?><div class="simple-list"><?php foreach($threads as $t): $other=(int)$t['customer_id']===$uid?$t['owner_name']:$t['customer_name']; ?><a href="<?= app_path('messages.php?conversation='.(int)$t['id']) ?>"><span><strong><?= h($t['listing_name']) ?></strong><small><?= h($other) ?> · <?= h(text_excerpt((string)$t['last_message'],65)) ?></small></span><?php if((int)$t['unread']): ?><b class="lg3-unread"><?= (int)$t['unread'] ?></b><?php endif; ?></a><?php endforeach; ?></div><?php else: ?><p class="muted">No conversations yet. Open a business profile and choose Message owner.</p><?php endif; ?></aside><section class="content-panel"><h2><?= $activeThread?h($activeThread['listing_name']):'Start a conversation' ?></h2><?php if($activeThread): ?><div class="lg3-chat-log"><?php foreach($messages as $m): ?><article class="lg3-chat-message <?= (int)$m['sender_id']===$uid?'mine':'theirs' ?>"><strong><?= h($m['sender_name']) ?></strong><p><?= nl2br(h($m['body'])) ?></p><small><?= h(date('M j, g:i A',strtotime($m['created_at']))) ?></small></article><?php endforeach; ?><?php if(!$messages): ?><p class="muted">Say hello to get the conversation started.</p><?php endif; ?></div><form method="post" class="studio-fields"><?= csrf_field() ?><input type="hidden" name="conversation_id" value="<?= (int)$activeThread['id'] ?>"><label>Your message<textarea name="body" rows="3" minlength="2" maxlength="2000" required></textarea></label><button class="button button-primary">Send message</button></form><?php elseif($targetListing): ?><p>Send a private message to the verified owner of <strong><?= h($targetListing['name']) ?></strong>.</p><form method="post" class="studio-fields"><?= csrf_field() ?><input type="hidden" name="listing_id" value="<?= (int)$targetListing['id'] ?>"><label>Message<textarea name="body" rows="5" minlength="2" maxlength="2000" required placeholder="Hello, I would like to ask about…"></textarea></label><button class="button button-primary">Start conversation</button></form><?php else: ?><p class="muted">Choose a conversation from the inbox or start from a business profile with an approved owner.</p><a class="button button-outline" href="<?= app_path('index.php') ?>">Browse businesses</a><?php endif; ?></section></div></main>
